        E(1, "Relatório de vendas CSV", "Leia <code>vendas.csv</code> (produto, quantidade, preco) com <code>csv.DictReader</code>. Calcule <code>faturamento</code> e <code>por_produto</code> ({produto: total}).",
          'import csv\nfaturamento = 0\npor_produto = {}\nwith open("vendas.csv", encoding="utf-8", newline="") as f:\n    for l in csv.DictReader(f):\n        v = int(l["quantidade"]) * float(l["preco"])\n        faturamento += v\n        por_produto[l["produto"]] = por_produto.get(l["produto"], 0) + v', 'assert faturamento == 86.5 and por_produto == {"café": 51.5, "pão": 35.0}', ["Converta quantidade e preço", "Acumule por produto"], s='open("vendas.csv", "w", encoding="utf-8").write("produto,quantidade,preco\\ncafé,2,12.5\\npão,10,3.5\\ncafé,2,13.25\\n")'),
        E(1, "Configuração com padrão", "Crie <code>salvar_config(dados)</code> (grava <code>config.json</code>) e <code>carregar_config()</code> que devolve o conteúdo, ou <code>{\"tema\": \"claro\", \"fonte\": 12}</code> se o arquivo não existir.",
          'import json\n\ndef salvar_config(dados):\n    with open("config.json", "w", encoding="utf-8") as f:\n        json.dump(dados, f, indent=2, ensure_ascii=False)\n\ndef carregar_config():\n    try:\n        with open("config.json", encoding="utf-8") as f:\n            return json.load(f)\n    except FileNotFoundError:\n        return {"tema": "claro", "fonte": 12}', 'assert carregar_config() == {"tema": "claro", "fonte": 12}\nsalvar_config({"tema": "escuro"})\nassert carregar_config() == {"tema": "escuro"}', ["Trate FileNotFoundError", "json.dump com indent=2"]),
        E(1, "Exceção personalizada", "Crie <code>SaldoInsuficienteError</code> com o atributo <code>faltando</code> e <code>sacar(saldo, valor)</code> que a lança quando o valor excede o saldo.",
          'class SaldoInsuficienteError(Exception):\n    def __init__(self, faltando):\n        super().__init__(f"Saldo insuficiente: faltam R$ {faltando:.2f}")\n        self.faltando = faltando\n\ndef sacar(saldo, valor):\n    if valor > saldo:\n        raise SaldoInsuficienteError(valor - saldo)\n    return saldo - valor', 'assert sacar(100, 30) == 70\ntry:\n    sacar(100, 150); assert False, "Deveria lançar"\nexcept SaldoInsuficienteError as e:\n    assert e.faltando == 50 and "50.00" in str(e)\nassert issubclass(SaldoInsuficienteError, Exception)', ["Herde de Exception", "Guarde o valor num atributo"]),
        E(1, "Arquivos .py por tamanho", "Na pasta atual há arquivos variados (com subpastas). Crie <code>py</code>: lista de tuplas (caminho relativo com <code>/</code>, tamanho em bytes) dos <code>.py</code>, do maior para o menor.",
          'from pathlib import Path\npy = sorted(((p.as_posix(), p.stat().st_size) for p in Path(".").rglob("*.py")), key=lambda x: -x[1])', 'assert py == [("src/app.py", 30), ("main.py", 12), ("src/util.py", 5)]', ["Path(\".\").rglob(\"*.py\")", "p.stat().st_size"], s='import os\nos.makedirs("src", exist_ok=True)\nfor n, t in [("main.py", 12), ("src/app.py", 30), ("src/util.py", 5), ("notas.txt", 99)]:\n    open(n, "w").write("x" * t)'),
